"use client";import {useState} from 'react';import {supabaseBrowser} from '@/lib/supabase/browser';import Link from 'next/link';export default function Login(){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState('');async function submit(e:React.FormEvent){e.preventDefault();const {error}=await supabaseBrowser().auth.signInWithPassword({email,password});if(error)setMessage(error.message);else window.location.href='/dashboard'}return <div className="panel max-w-md"><h1>Login</h1><form onSubmit={submit}><label>Email</label><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/><label>Password</label><input type="password" required value={password} onChange={e=>setPassword(e.target.value)}/><button className="mt-4">Masuk</button></form><p className="mt-3">{message}</p><Link className="link" href="/register">Daftar siswa</Link></div>}